for (const lang of ["de", "es", "fr", "it"] as const) {
  for (const slug of prioritySlugs) {
    const [title, excerpt, keyword] = titles[lang][slug];
    localizedMeta[lang][slug] = {
      title,
      excerpt,
      keyword,
      sourceNote: lang === "de" ? "Plattformrolle und Beleggrenzen am 18. September 2026 anhand aktueller öffentlicher Hacoo-Seiten geprüft." : lang === "es" ? "Función de la plataforma y límites de evidencia revisados en materiales públicos actuales de Hacoo el 18 de septiembre de 2026." : lang === "fr" ? "Rôle de la plateforme et limites des preuves revérifiés dans les contenus publics actuels de Hacoo le 18 septembre 2026." : "Ruolo della piattaforma e limiti delle prove ricontrollati nei materiali pubblici Hacoo il 18 settembre 2026.",
      imageAlt: title,
      imageCaption: excerpt,
      sections: labels[lang].map((heading) => [heading, localeCopy[lang]]) as readonly (readonly [string, string])[],
    };
  }
}

export const priorityArticleTexts: Record<Lang, Record<PrioritySlug, ArticleText>> = {
  en: priorityArticles,
  ...localizedMeta,
};
